(()=>{window.__bunnyLoading=true;let progress=0,failed=false;const curtain=document.querySelector('#startup-curtain'),frame=curtain.querySelector('iframe');const raw=(new URLSearchParams(location.search).get('intent')!=='new'&&window.BunnyBotSave?.summary()?.difficulty)||new URLSearchParams(location.search).get('difficulty'),difficulty=['low','medium','high'].includes(raw)?raw:'medium';const english=localStorage.getItem('bunny-language')==='en';curtain.setAttribute('aria-label',english?'Preparing table':'正在準備牌桌');frame.title=english?'Four-player loading screen':'四人對戰載入畫面';frame.src='/design/lobby/ready/index.html?loading=1&difficulty='+difficulty;const send=()=>frame.contentWindow?.postMessage({type:'bunny:loading-progress',progress,failed},location.origin);frame.addEventListener('load',send);window.BunnyStartup={progress(value){progress=value;failed=false;document.documentElement.dataset.startupState='loading';document.documentElement.dataset.startupProgress=String(value);send()},fail(){failed=true;document.documentElement.dataset.startupState='error';send()},finish(){if(!window.__bunnyLoading)return;window.__bunnyLoading=false;document.documentElement.dataset.startupState='ready';window.dispatchEvent(new Event('bunny:table-ready'));curtain.classList.add('finished');setTimeout(()=>curtain.remove(),260)}};document.documentElement.dataset.startupState='loading';window.addEventListener('message',event=>{if(event.origin===location.origin&&event.source===frame.contentWindow&&event.data?.type==='bunny:retry-loading'){location.reload()}})})();
